startAmbient() {
  if (!this.ctx || this.ambientNode) return;
  const src = this.ctx.createBufferSource();
  src.buffer = this.buffers.ambient;
  src.loop = true;
  const gain = this.ctx.createGain();
  gain.gain.value = this.settings.get('audio.ambient') / 100;
  src.connect(gain);
  gain.connect(this.master);
  src.start();
  this.ambientNode = { src, gain };
}

startMusic() {
  if (!this.ctx || this.musicNode) return;
  const src = this.ctx.createBufferSource();
  src.buffer = this.buffers.music;
  src.loop = true;
  const gain = this.ctx.createGain();
  gain.gain.value = this.settings.get('audio.music') / 100;
  src.connect(gain);
  gain.connect(this.master);
  src.start();
  this.musicNode = { src, gain };
}

updateAmbient() {
  if (this.ambientNode) {
    this.ambientNode.gain.gain.value = this.settings.get('audio.ambient') / 100;
  }
  if (this.musicNode) {
    this.musicNode.gain.gain.value = this.settings.get('audio.music') / 100;
  }
  this._applyVolumes();
}
